const event = $('Parsear Evento').first().json;
const items = $input.all();

const ZONE_LABELS = {
  ZONA_A: 'Orquideario',
  ZONA_B: 'Jardín',
  ZONA_C: 'Terraza',
  ZONA_D: 'Ventanas',
  EXTERIOR: 'Exterior'
};

const STATUS_LABELS = {
  PENDING: 'Pendiente',
  COMPLETED: 'Completada',
  CANCELLED: 'Cancelada'
};

const timeMap = {
  'today': 'Hoy',
  'week': 'Esta Semana',
  'next-week': 'Prox. Semana',
  'month': 'Este Mes',
  'next-month': 'Prox. Mes',
  'all': 'Todos los Tiempos'
};

const statusMap = {
  'PENDING': 'Pendientes',
  'COMPLETED': 'Completadas',
  'CANCELLED': 'Canceladas',
  'all': 'Todos los Estados'
};

const timeLabel = timeMap[event.timePreset] || 'Todos los Tiempos';
const statusLabel = statusMap[event.statusPreset] || 'Todos los Estados';

const DAYS = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const MONTHS = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

function formatDate(dateObj) {
  const dayName = DAYS[dateObj.getDay()];
  const dayNum = dateObj.getDate();
  const monthName = MONTHS[dateObj.getMonth()];
  return `${dayName} ${dayNum} ${monthName}`;
}

function formatTime(dateObj) {
  let hours = dateObj.getHours();
  const minutes = dateObj.getMinutes().toString().padStart(2, '0');
  const ampm = hours >= 12 ? 'pm' : 'am';
  hours = hours % 12;
  hours = hours ? hours : 12;
  return `${hours}:${minutes} ${ampm}`;
}

function formatZones(zones) {
  if (!zones) return 'General';
  let zoneArray = Array.isArray(zones) ? zones : [zones];
  if (typeof zones === 'string' && zones.startsWith('{')) {
    zoneArray = zones.replace(/[{}]/g, '').split(',');
  }
  return zoneArray.map(z => ZONE_LABELS[z.trim()] || z.trim()).join(', ');
}

if (items.length === 0 || !items[0].json.id) {
  return [{
    json: {
      chatId: event.chatId,
      messageId: event.messageId,
      replyText: `\u200B\n*Tareas de Dosificación*\n${timeLabel}\n${statusLabel}\n\nSin tareas registradas` 
    }
  }];
}

let replyText = `\u200B\n*Tareas de Dosificación*\n${timeLabel}\n${statusLabel}\n\n`;
items.forEach((item, index) => {
  const row = item.json;
  const agroName = row.agrochemicalName || 'Producto';
  const statusStr = STATUS_LABELS[row.status] || row.status;
  const zonesStr = formatZones(row.zones);
  const dateObj = new Date(row.scheduledAt);
  const dateStr = formatDate(dateObj);
  const timeStr = formatTime(dateObj);
  const prepStr = row.preparation ? row.preparation.trim() : '';

  replyText += `${index + 1}. ${agroName} - ${statusStr}\n`;
  if (prepStr) {
    replyText += `   Receta: ${prepStr}\n`;
  }
  replyText += `   Zonas: ${zonesStr}\n`;
  replyText += `   Fecha: ${dateStr}\n`;
  replyText += `   Hora: ${timeStr}\n\n`;
});

return [{
  json: {
    chatId: event.chatId,
    messageId: event.messageId,
    replyText: replyText.trimEnd()
  }
}];
